vec3 pal( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d )
{
    return a + b*cos( 6.28318*(c*t+d) );
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord*2.- iResolution.xy)/iResolution.y;
    vec2 uv0 = uv;
    vec3 col = vec3(0.647,0.659,0.753);
    vec3 finalColor = vec3(1.);
    uv0 = vec2(sin(2.*iTime)/2.);

    uv = fract(uv)-.5*exp(-length(uv0)*sin(iTime*2.)/8.);

    float d = 1.; //sin(uv.x * uv.y + iTime);

    uv += vec2( iTime*.02);
    uv = (fract(uv*4.)-.5);
    d = .6/abs(d);
    d *= length(uv) -1.;
    d = 0.1/d;
    d = d/.1;
    d = abs(d);

    d *= length(uv)-.5 *exp(-length(uv0));
    d = abs(d);

    d = 0.1/d;
    vec3 a = vec3(.5);
    vec3 b = a;
    vec3 c = vec3(1.);
    vec3 dd = vec3(-.250,-.125,.123);
    finalColor = col*d*pal(iTime,a,b,c,dd);

    // Output to screen
    fragColor = vec4(finalColor,.1);
}
